  const CAPABILITIES = Object.freeze({ "async-command": ["institution", "reports", "personnel", "research", "infrastructure", "tasks", "known-complex"], "field-researcher": ["objectives", "surroundings", "team", "communications", "evidence", "equipment", "risk", "known-route"], "local-anomaly": ["base", "archive", "artifacts", "questions", "routes", "preparation", "excursion"], lost: ["surroundings", "route-fragments", "landmarks", "resources", "notes"] });
  const actions = (projection) => panel("Available actions", projection.available_actions.length ? `<div class="action-grid">${projection.available_actions.map((item) => `<button type="button" class="action-button" data-game-action="${escape(item.type)}" data-testid="action-${escape(item.type)}">${escape(actionLabel(item.type))}</button>`).join("")}</div>` : empty("No action is available right now."), 'data-testid="actions"');
