    const localDisabled = disabled || !local.available ? "disabled" : ""; const standardDisabled = disabled || !standard.available ? "disabled" : ""; const radioReady = projection.phase?.phase_id === "STANDARD_RADIO_CHECK"; const standardSelected = radioReady ? "selected" : ""; const localSelected = radioReady ? "" : "selected";
    return `<aside class="communications-surface" data-testid="q4-communications"><header><div><p class="eyebrow">COMMUNICATIONS</p><h2>One chronological channel record</h2></div><span class="channel-state" data-radio-state="${escape(standard.state ?? "unavailable")}">${escape(standardState)}</span></header><section class="compact-team" data-testid="q4-team-status"><h3>Immediate team condition</h3>${roster}</section><ol class="communication-timeline" aria-label="Chronological communication history">${timeline}</ol><form id="q4-comms-form" data-testid="q4-comms-form"><div class="mechanical-channel-selector" data-channel-current="${radioReady ? "standard" : "local"}"><div class="mechanical-channel-switch" role="group" aria-label="Channel toggle"><span class="switch-slot switch-standard ${standardSelected ? "active" : ""}">STANDARD</span><span class="switch-track" aria-hidden="true">${standardSelected ? "[■■□□]" : "[□□■■]"}</span><span class="switch-slot switch-local ${localSelected ? "active" : ""}">LOCAL</span></div><label class="channel-select-label">Channel<select name="channel" data-testid="q4-channel"><option value="local" ${localDisabled} ${localSelected}>LOCAL · nearby personnel (${escape(localState)})</option><option value="standard" ${standardDisabled} ${standardSelected}>STANDARD · operations desk (${escape(standardState)})</option></select></label></div><p class="channel-explanation">LOCAL is heard by all nearby participating personnel. STANDARD is a radio transmission; delivery and acknowledgment are recorded separately.</p><label class="q4-composer">Message<input name="text" autocomplete="off" placeholder="Compose your own speech or transmission" ${disabled ? "disabled" : ""}></label><button type="submit" ${disabled ? "disabled" : ""}>Submit transmission</button></form><p class="comms-state"><span data-channel-state="local">${escape(localState)}</span><span data-channel-state="standard">${escape(standardState)}</span></p></aside>`;
